// sketch.ino
// Плата: ESP32-S3, режим USB-OTG
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

const char* BAT_PATH = "%USERPROFILE%\\script.bat";

void setup() {
  Keyboard.begin();
  USB.begin();

  // Даём ОС время распознать устройство (на ESP32-S3 это дольше, чем на Arduino)
  delay(5000);

  // Win + R
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1000);

  // Печатаем "cmd" — раскладка должна быть английской!
  Keyboard.print("cmd");
  pressEnter();
  delay(2000);

  // Создаём script.bat по строкам
  Keyboard.print("echo @echo off>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  Keyboard.print("echo color 2 >>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  Keyboard.print("echo dir/s>>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  Keyboard.print("echo goto x>>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  // Запускаем батник
  Keyboard.print("start ");
  Keyboard.print(BAT_PATH);
  pressEnter();

  // Полноэкранный режим (F11 в Windows Terminal)
  delay(2000);
  Keyboard.press(KEY_F11);
  delay(100);
  Keyboard.releaseAll();
